def replace_words(dictionary, sentence):
    roots = set(dictionary)
    answer = []
    for word in sentence.split():
        replacement = word
        for length in range(1, len(word) + 1):
            if word[:length] in roots:
                replacement = word[:length]
                break
        answer.append(replacement)
    return ' '.join(answer)

